parameters.subject:
={{ 
  !$('Send Pending Notification').isExecuted 
    ? (
        (Number($('Prepare Approval Context').first().json.amount) <= 0 || !$('Prepare Approval Context').first().json.amount)
          ? 'Invoice ' + $('Prepare Approval Context').first().json.invoice_id + ' - Rejected Due to Invalid Request'
          : 'Invoice ' + $('Prepare Approval Context').first().json.invoice_id + ' - Auto-Approved'
      )
    : (
        ($('Evaluate Stage 1 Decision').isExecuted && (['decline', 'reject'].includes(($('Stage 1: Firm Admin Approval').first()?.json?.data?.Decision || '').toString().toLowerCase()) || $('Stage 1: Firm Admin Approval').first()?.json?.data?.approved === false))
          ? 'Invoice ' + $('Prepare Approval Context').first().json.invoice_id + ' - Declined by Firm Administrator'
          : (
              ($('Evaluate Stage 2 Decision').isExecuted && (['decline', 'reject'].includes(($('Stage 2: Client Approval').first()?.json?.data?.Decision || '').toString().toLowerCase()) || $('Stage 2: Client Approval').first()?.json?.data?.approved === false))
                ? 'Invoice ' + $('Prepare Approval Context').first().json.invoice_id + ' - Declined by Client'
                : (
                    ($('Evaluate Stage 2 Decision').isExecuted && (($('Stage 2: Client Approval').first()?.json?.data?.Decision || '').toString().toLowerCase() === 'approve' || $('Stage 2: Client Approval').first()?.json?.data?.approved === true))
                      ? 'Invoice ' + $('Prepare Approval Context').first().json.invoice_id + ' - Fully Approved'
                      : 'URGENT SLA ALERT: Invoice ' + $('Prepare Approval Context').first().json.invoice_id + ' - Approval Window Expired'
                  )
            )
      )
}}

