value.outcome_status:
={{ 
  !$('Send Pending Notification').isExecuted 
    ? (
        (Number($('Prepare Approval Context').first().json.amount) <= 0 || !$('Prepare Approval Context').first().json.amount)
          ? 'Rejected due to invalid request.'
          : 'Auto-Approved'
      )
    : (
        ($('Evaluate Stage 1 Decision').isExecuted && (['decline', 'reject'].includes(($('Stage 1: Firm Admin Approval').first()?.json?.data?.Decision || $('Stage 1: Firm Admin Approval').first()?.json?.data?.decision || '').toString().toLowerCase()) || $('Stage 1: Firm Admin Approval').first()?.json?.data?.approved === false))
          ? ('Stage 1: Rejected by Firm Administrator - ' + ($('Stage 1: Firm Admin Approval').first()?.json?.data?.['Rejection Reason / Notes'] || 'Declined by Firm Admin'))
          : (
              ($('Evaluate Stage 2 Decision').isExecuted && (['decline', 'reject'].includes(($('Stage 2: Client Approval').first()?.json?.data?.Decision || $('Stage 2: Client Approval').first()?.json?.data?.decision || '').toString().toLowerCase()) || $('Stage 2: Client Approval').first()?.json?.data?.approved === false))
                ? ('Stage 2: Rejected by Client - ' + ($('Stage 2: Client Approval').first()?.json?.data?.['Rejection Reason / Notes'] || 'Declined by Client'))
                : (
                    ($('Evaluate Stage 2 Decision').isExecuted && (($('Stage 2: Client Approval').first()?.json?.data?.Decision || $('Stage 2: Client Approval').first()?.json?.data?.decision || '').toString().toLowerCase() === 'approve' || $('Stage 2: Client Approval').first()?.json?.data?.approved === true))
                      ? 'Stage 2: Approved by Client (Fully Approved)'
                      : 'Approval Window Expired (Timed Out)'
                  )
            )
      )
}}
